sql_query:
SELECT "Total sample size"
FROM clinical_trials
WHERE "Included in MA" = 'No' AND "Name of ICI" = 'Atezolizumab' AND "Trial phase" = 'Phase 2';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Total sample size" AS source_value FROM clinical_trials WHERE "Included in MA" = 'No' AND "Name of ICI" = 'Atezolizumab' AND "Trial phase" = 'Phase 2'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_size_bucket(source_value) AS "size_bucket"
FROM base;
